46	  /**
47	   * Search across all discourse nodes (files that have frontmatter nodeTypeId)
48	   */
49	  searchDiscourseNodesByTitle = (
50	    query: string,
51	    nodeTypeId?: string,
52	  ): TFile[] => {
53	    if (!query || query.length < this.MIN_QUERY_LENGTH) {
54	      return [];
55	    }
56	    const datacore = this.getReadyDatacore();
57	    if (!datacore) {
58	      return this.fallbackSearchDiscourseNodesByTitle(query, nodeTypeId);
59	    }
60	
61	    try {
62	      const dcQuery = nodeTypeId
63	        ? `@page and exists(nodeTypeId) and nodeTypeId = "${nodeTypeId}"`
64	        : "@page and exists(nodeTypeId)";
65	      const potentialNodes = datacore.query(dcQuery);
66	
67	      const searchResults = potentialNodes.filter((p: DatacorePage) =>
68	        this.fuzzySearch(p.$name, query),
69	      );
70	
71	      const files = searchResults
72	        .map((dcFile: DatacorePage) => {
73	          if (dcFile && dcFile.$path) {
74	            const realFile = this.app.vault.getAbstractFileByPath(dcFile.$path);
75	            if (realFile && realFile instanceof TFile) return realFile;
76	          }
77	          return null;
78	        })
79	        .filter((f): f is TFile => f instanceof TFile);
80	
81	      return files.reverse();
82	    } catch (error) {
83	      console.error("Error in searchDiscourseNodesByTitle:", error);
84	      return this.fallbackSearchDiscourseNodesByTitle(query, nodeTypeId);
85	    }
86	  };
