114	  searchCompatibleNodeByTitle = ({
115	    query,
116	    compatibleNodeTypeIds,
117	    activeFile,
118	    selectedRelationType,
119	  }: {
120	    query: string;
121	    compatibleNodeTypeIds: string[];
122	    activeFile: TFile;
123	    selectedRelationType: string;
124	  }): TFile[] => {
125	    if (!query || query.length < this.MIN_QUERY_LENGTH) {
126	      return [];
127	    }
128	    const datacore = this.getReadyDatacore();
129	    if (!datacore) {
130	      return this.fallbackSearchCompatibleNodeByTitle({
131	        query,
132	        compatibleNodeTypeIds,
133	        activeFile,
134	        selectedRelationType,
135	      });
136	    }
137	
138	    try {
139	      const dcQuery = `@page and exists(nodeTypeId) and ${compatibleNodeTypeIds
140	        .map((id) => `nodeTypeId = "${id}"`)
141	        .join(" or ")}`;
142	
143	      const potentialNodes = datacore.query(dcQuery);
144	      const searchResults = potentialNodes.filter((p: DatacorePage) => {
145	        return this.fuzzySearch(p.$name, query);
146	      });
147	
148	      let existingRelatedFiles: string[] = [];
149	      if (selectedRelationType) {
150	        const fileCache = this.app.metadataCache.getFileCache(activeFile);
151	        const existingRelations: string[] =
152	          (fileCache?.frontmatter?.[selectedRelationType] as string[]) || [];
153	
154	        existingRelatedFiles = existingRelations.map((relation: string) => {
155	          const match = relation.match(/\[\[(.*?)(?:\|.*?)?\]\]/);
156	          return match?.[1] ?? relation.replace(/^\[\[|\]\]$/g, "");
157	        });
158	      }
159	      const finalResults = searchResults
160	        .map((dcFile: DatacorePage) => {
161	          if (dcFile && dcFile.$path) {
162	            const realFile = this.app.vault.getAbstractFileByPath(dcFile.$path);
163	            if (realFile && realFile instanceof TFile) {
164	              return realFile;
165	            }
166	          }
167	          return null;
168	        })
169	        .filter((f): f is TFile => f instanceof TFile)
170	        .filter((file: TFile) => {
171	          if (file.path === activeFile.path) return false;
172	
173	          if (
174	            selectedRelationType &&
175	            existingRelatedFiles.some((existingFile) => {
176	              return (
177	                file.basename === existingFile.replace(/\.md$/, "") ||
178	                file.name === existingFile
179	              );
180	            })
181	          ) {
182	            return false;
183	          }
184	
185	          return true;
186	        });
187	
188	      return finalResults;
189	    } catch (error) {
190	      console.error("Error in searchNodeByTitle:", error);
191	      return this.fallbackSearchCompatibleNodeByTitle({
192	        query,
193	        compatibleNodeTypeIds,
194	        activeFile,
195	        selectedRelationType,
196	      });
197	    }
198	  };
