200	  /**
201	   * Enhanced fuzzy search implementation
202	   * Returns true if the search term is found within the target string
203	   * with tolerance for typos and partial matches
204	   */
205	  fuzzySearch(target: string, search: string): boolean {
206	    if (!search || !target) return false;
207	
208	    const targetLower = target.toLowerCase();
209	    const searchLower = search.toLowerCase();
210	
211	    if (targetLower.includes(searchLower)) {
212	      return true;
213	    }
214	
215	    if (searchLower.length > targetLower.length) {
216	      return false;
217	    }
218	
219	    if (targetLower.startsWith(searchLower)) {
220	      return true;
221	    }
222	
223	    let searchIndex = 0;
224	    let consecutiveMatches = 0;
225	    const MIN_CONSECUTIVE = Math.min(2, searchLower.length);
226	
227	    for (
228	      let i = 0;
229	      i < targetLower.length && searchIndex < searchLower.length;
230	      i++
231	    ) {
232	      if (targetLower[i] === searchLower[searchIndex]) {
233	        searchIndex++;
234	        consecutiveMatches++;
235	
236	        if (
237	          consecutiveMatches >= MIN_CONSECUTIVE &&
238	          searchIndex >= searchLower.length * 0.7
239	        ) {
240	          return true;
241	        }
242	      } else {
243	        consecutiveMatches = 0;
244	      }
245	    }
246	
247	    return searchIndex === searchLower.length;
248	  }
