250	  scanForBulkImportCandidates(
251	    patterns: BulkImportPattern[],
252	    validNodeTypes: DiscourseNode[],
253	  ): BulkImportCandidate[] {
254	    const candidates: BulkImportCandidate[] = [];
255	
256	    const datacore = this.getReadyDatacore();
257	    if (!datacore) {
258	      return this.fallbackScanVault(patterns, validNodeTypes);
259	    }
260	
261	    try {
262	      let dcQuery: string;
263	
264	      if (validNodeTypes.length === 0) {
265	        dcQuery = "@page";
266	      } else {
267	        const validIdConditions = validNodeTypes
268	          .map((nt) => `nodeTypeId != "${nt.id}"`)
269	          .join(" and ");
270	
271	        dcQuery = `@page and (!exists(nodeTypeId) or (${validIdConditions}))`;
272	      }
273	
274	      const potentialPages = datacore.query(dcQuery);
275	
276	      for (const page of potentialPages) {
277	        const fileName = page.$name;
278	
279	        for (const pattern of patterns) {
280	          if (!pattern.enabled || !pattern.alternativePattern.trim()) continue;
281	
282	          const regex = getDiscourseNodeFormatExpression(
283	            pattern.alternativePattern,
284	          );
285	
286	          if (regex.test(fileName)) {
287	            if (!page.$path) continue;
288	            const file = this.app.vault.getAbstractFileByPath(page.$path);
289	            if (file && file instanceof TFile) {
290	              const extractedContent = extractContentFromTitle(
291	                pattern.alternativePattern,
292	                fileName,
293	              );
294	
295	              const matchedNodeType = validNodeTypes.find(
296	                (nt) => nt.id === pattern.nodeTypeId,
297	              );
298	
299	              if (!matchedNodeType) {
300	                continue;
301	              }
302	
303	              candidates.push({
304	                file,
305	                matchedNodeType,
306	                alternativePattern: pattern.alternativePattern,
307	                extractedContent,
308	                selected: false,
309	              });
310	            }
311	            break; // Stop checking other patterns for this file
312	          }
313	        }
314	      }
315	
316	      return candidates;
317	    } catch (error) {
318	      console.error(
319	        "Error in datacore bulk scan, falling back to vault iteration:",
320	        error,
321	      );
322	      return this.fallbackScanVault(patterns, validNodeTypes);
323	    }
324	  }
