551	  private fallbackSearchCompatibleNodeByTitle({
552	    query,
553	    compatibleNodeTypeIds,
554	    activeFile,
555	    selectedRelationType,
556	  }: {
557	    query: string;
558	    compatibleNodeTypeIds: string[];
559	    activeFile: TFile;
560	    selectedRelationType: string;
561	  }): TFile[] {
562	    const fileCache = this.app.metadataCache.getFileCache(activeFile);
563	    const frontmatter = fileCache?.frontmatter as
564	      | Record<string, unknown>
565	      | undefined;
566	    const rawExistingRelations = frontmatter?.[selectedRelationType];
567	    const existingRelations = Array.isArray(rawExistingRelations)
568	      ? (rawExistingRelations as string[])
569	      : rawExistingRelations
570	        ? [String(rawExistingRelations)]
571	        : [];
572	    const existingRelatedFiles = existingRelations.map((relation) => {
573	      const match = relation.match(/\[\[(.*?)(?:\|.*?)?\]\]/);
574	      return match?.[1] ?? relation.replace(/^\[\[|\]\]$/g, "");
575	    });
576	
577	    return this.app.vault
578	      .getMarkdownFiles()
579	      .filter((file) => {
580	        if (file.path === activeFile.path) return false;
581	        const fm = this.app.metadataCache.getFileCache(file)?.frontmatter as
582	          | Record<string, unknown>
583	          | undefined;
584	        if (!compatibleNodeTypeIds.includes(String(fm?.nodeTypeId ?? ""))) {
585	          return false;
586	        }
587	        if (!this.fuzzySearch(file.basename, query)) return false;
588	        return !existingRelatedFiles.some(
589	          (existingFile) =>
590	            file.basename === existingFile.replace(/\.md$/, "") ||
591	            file.name === existingFile,
592	        );
593	      })
594	      .reverse();
595	  }
