647	  private fallbackScanVault(
648	    patterns: BulkImportPattern[],
649	    validNodeTypes: DiscourseNode[],
650	  ): BulkImportCandidate[] {
651	    const candidates: BulkImportCandidate[] = [];
652	    const allFiles = this.app.vault.getMarkdownFiles();
653	
654	    for (const file of allFiles) {
655	      const fileName = file.basename;
656	      const fileCache = this.app.metadataCache.getFileCache(file);
657	      const currentNodeTypeId = fileCache?.frontmatter?.nodeTypeId as
658	        | string
659	        | undefined;
660	
661	      if (
662	        currentNodeTypeId &&
663	        validNodeTypes.some((nt) => nt.id === currentNodeTypeId)
664	      ) {
665	        continue;
666	      }
667	
668	      for (const pattern of patterns) {
669	        if (!pattern.enabled || !pattern.alternativePattern.trim()) continue;
670	
671	        const regex = getDiscourseNodeFormatExpression(
672	          pattern.alternativePattern,
673	        );
674	
675	        if (regex.test(fileName)) {
676	          const extractedContent = extractContentFromTitle(
677	            pattern.alternativePattern,
678	            fileName,
679	          );
